  DH(QI.text_data_en, "SCR_TEXT_1478", " %%");
  DH(QI.text_data_en, "SCR_TEXT_1483", "* (The box is empty.)/%%");
  DH(QI.text_data_en, "SCR_TEXT_1492", "* Hello...&* Would you like some&  Nice Cream...?/");
  DH(QI.text_data_en, "SCR_TEXT_1493", "* It's the frozen treat...&* That warms your heart./");
  DH(QI.text_data_en, "SCR_TEXT_1494", "* Now only 12G!& &         Yes         No \\C");
