  DH(QI.text_data_en, "SCR_TEXT_2882", "* (Play it?)& &         Play it     No\\C");
  DH(QI.text_data_en, "SCR_TEXT_2883", " ");
  DH(QI.text_data_en, "SCR_TEXT_2886", "* (This CD is labelled&  \"Spookwave.\")/");
  DH(QI.text_data_en, "SCR_TEXT_2887", "* (This CD is playing.)&* (Turn it off?)&         Stop it     No\\C");
  DH(QI.text_data_en, "SCR_TEXT_2888", " ");
