  DH(QI.text_data_en, "SCR_TEXT_5581", "* Thanks a million ./%%");
  DH(QI.text_data_en, "SCR_TEXT_5585", "* (No response.)/%%");
  DH(QI.text_data_en, "SCR_TEXT_5598", "* (You pour the Sea Tea under&  the door.)/");
  DH(QI.text_data_en, "SCR_TEXT_5599", "* HUH !?!?!?!^2?&* That's just the way I want ^1!&* Here's a tip ./");
  DH(QI.text_data_en, "SCR_TEXT_5600", "* (You got 99G.)/%%");
  DH(QI.text_data_en, "SCR_TEXT_5604", "* ..^1.&* No you don't ./%%");
