  DH(QI.text_data_en, "SCR_TEXT_5614", "* (Knock knock)./");
  DH(QI.text_data_en, "SCR_TEXT_5617", "* Oooooaaah ^1!&* Room service !/");
  DH(QI.text_data_en, "SCR_TEXT_5618", "* Got my \"Cinnamon Bun\" ?& &         Yes         No\\C");
  DH(QI.text_data_en, "SCR_TEXT_5619", " ");
