  DH(QI.text_data_en, "SCR_TEXT_5632", "* (No response.)/%%");
  DH(QI.text_data_en, "SCR_TEXT_5646", "* (You flatten the Cinnamon Bun&  until it's paper thin.)&* (You slide it under the door.)/");
  DH(QI.text_data_en, "SCR_TEXT_5647", "* HUH !?!?!?!^2?&* That's just the way I want ^1!&* Here's a tip ./");
  DH(QI.text_data_en, "SCR_TEXT_5648", "* (You got 99G.)/%%");
  DH(QI.text_data_en, "SCR_TEXT_5652", "* ..^1.&* No you don't ./%%");
  DH(QI.text_data_en, "SCR_TEXT_5657", "* Then ...!?/%%");
  DH(QI.text_data_en, "SCR_TEXT_5662", "* (You hear shuffling.)/");
