  DH(QI.text_data_en, "SCR_TEXT_5713", "* (A single hushpuppy slides&  out from under the door.)/");
  DH(QI.text_data_en, "SCR_TEXT_5714", "* (You got Hush Puppy.)/%%");
  DH(QI.text_data_en, "SCR_TEXT_5720", "* (You put a Hot Cat in front&  of the door.)/");
  DH(QI.text_data_en, "SCR_TEXT_5721", "* (You hear growling...)/%%");
  DH(QI.text_data_en, "SCR_TEXT_5727", "* (You put a Dog Salad in front&  of the door.^1)&* (It slides underneath.)/");
  DH(QI.text_data_en, "SCR_TEXT_5728", "* (...)/");
  DH(QI.text_data_en, "SCR_TEXT_5729", "* (The Dog Salad was absorbed&  by the darkness.)/%%");
  DH(QI.text_data_en, "SCR_TEXT_5736", "* (You put a Dog Residue in&  front of the door.)/");
  DH(QI.text_data_en, "SCR_TEXT_5737", "* (It slides underneath the door^1,&  as if pulled by a magnet.)/");
  DH(QI.text_data_en, "SCR_TEXT_5738", "* (...)/");
  DH(QI.text_data_en, "SCR_TEXT_5743", "* (ZOMMM!!^1!)&* (It shoots back out at a&  high speed!)/%%");
