  DH(QI.text_data_en, "SCR_TEXT_5755", " %%");
  DH(QI.text_data_en, "SCR_TEXT_5761", "* Yes^1, we know^1.&* The elevator to the city&  is NOT working./");
  DH(QI.text_data_en, "SCR_TEXT_5762", "* Because of this incident^1, rooms&  are running at a special rate!/");
  DH(QI.text_data_en, "SCR_TEXT_5763", "* 200G a room^1. Interested^1?& &         Stay        Do not\\C");
  DH(QI.text_data_en, "SCR_TEXT_5764", " ");
  DH(QI.text_data_en, "SCR_TEXT_5768", "* 200G a room^1. Interested^1?& &         Stay        Do not\\C");
  DH(QI.text_data_en, "SCR_TEXT_5769", " ");
  DH(QI.text_data_en, "SCR_TEXT_5774", "* Did you enjoy your stay?/");
  DH(QI.text_data_en, "SCR_TEXT_5775", "* What^1?&* Room..^1.&* Key?/");
  DH(QI.text_data_en, "SCR_TEXT_5776", "* No^1, we don't do that./");
