  DH(QI.text_data_en, "SCR_TEXT_5857", "");
  DH(QI.text_data_en, "SCR_TEXT_5863", "Then it is agreed./");
  DH(QI.text_data_en, "SCR_TEXT_5864", "You will give me your SOUL.& &         Yes         No\\C");
