  DH(QI.text_data_en, "obj_adate_972", "\\E3L-like t-telling me&that y-you'll b-beat&up anyone that&g-gets in my way.../%%");
  DH(QI.text_data_en, "obj_adate_976", "\\E9WH-WHAT!?/");
  DH(QI.text_data_en, "obj_adate_977", "\\M1UNDYNE WOULD NEVER^1,&UH..../");
  DH(QI.text_data_en, "obj_adate_978", "\\E3.../");
  DH(QI.text_data_en, "obj_adate_979", "\\M0.../");
