  DH(QI.text_data_en, "obj_adate_999", "I'M MADLY IN LOVE&WITH YOU!!!/");
  DH(QI.text_data_en, "obj_adate_1000", "HOLD ME^1, UNDYNE!^1!&HOLD ME!!!/%%");
