  DH(QI.text_data_en, "obj_adate_1236", "WHAT did you just&say?/%%");
  DH(QI.text_data_en, "obj_adate_1259", "\\E1U..^1. Undyne^1!&I..^1. was..^1. just.../%%");
  DH(QI.text_data_en, "obj_adate_1271", "\\F6Hey^1, woah^1, wait&a second!/");
  DH(QI.text_data_en, "obj_adate_1272", "Your outfit's really&cute^1!&What's the occasion?/");
  DH(QI.text_data_en, "obj_adate_1273", "\\F0.\\E0../");
  DH(QI.text_data_en, "obj_adate_1274", "\\F2W\\E1ait a second./");
  DH(QI.text_data_en, "obj_adate_1275", "\\F1Are you two.../");
  DH(QI.text_data_en, "obj_adate_1276", "\\F3On a date?/%%");
  DH(QI.text_data_en, "obj_adate_1287", "\\E1UHHH^1, \\F4YES!/");
  DH(QI.text_data_en, "obj_adate_1288", "\\E7I mean^1, \\F5UHHH NO!/");
  DH(QI.text_data_en, "obj_adate_1289", "\\E3I mean^1, \\F7we were^1,& bu^1t%");
  DH(QI.text_data_en, "obj_adate_1290", "\\E1I mean^1, actually we&were \\F3only romantically&roleplaying as you!/%%");
  DH(QI.text_data_en, "obj_adate_1300", "\\F3WHAT???/%%");
  DH(QI.text_data_en, "obj_adate_1311", "\\E8I MEAN!!!/");
  DH(QI.text_data_en, "obj_adate_1312", "\\E3I mean.../");
  DH(QI.text_data_en, "obj_adate_1313", "Undyne..^1.&I.../%%");
  DH(QI.text_data_en, "obj_adate_1326", "\\F4I've been lying to&you!/%%");
  DH(QI.text_data_en, "obj_adate_1336", "\\F3WHAT??^1?&ABOUT WHAT???/%%");
  DH(QI.text_data_en, "obj_adate_1349", "About... well.../");
  DH(QI.text_data_en, "obj_adate_1350", "\\E2Everything!/%%");
