  DH(QI.text_data_en, "obj_flowey_master_1192", "\\E5* Cry into the&  darkness!/");
  DH(QI.text_data_en, "obj_flowey_master_1193", "\\E8\"Mommy^1! Daddy^1!\"&\"Somebody help!\"/");
