  DH(QI.text_data_en, "obj_flowey_master_1261", "%%%");
  DH(QI.text_data_en, "obj_flowey_master_1276", "* .../");
  DH(QI.text_data_en, "obj_flowey_master_1277", "\\E0* But nobody came./");
  DH(QI.text_data_en, "obj_flowey_master_1278", "\\E2* Boy^1!&* What a shame!/");
  DH(QI.text_data_en, "obj_flowey_master_1279", "\\E7* Nobody else.../");
  DH(QI.text_data_en, "obj_flowey_master_1280", "* Is gonna get to&  see you DIE!!!/%%");
  DH(QI.text_data_en, "obj_flowey_master_1281", "%%%");
  DH(QI.text_data_en, "obj_flowey_master_1320", "* What^4? %");
  DH(QI.text_data_en, "obj_flowey_master_1321", "\\E1* How'd you...^4? %");
