  DH(QI.text_data_en, "obj_gameintro_fake_44", "Long ago^1, two races&ruled over Earth^1:&HUMANS and MONSTERS. \\E1 ^1 %");
  DH(QI.text_data_en, "obj_gameintro_fake_45", "One day^1, th^7ey all&disappeared without&a trace.");
