  DH(QI.text_data_en, "obj_heartdefeated_200_1", "  \\[C]^1!&  Stay determined.../%%");
  DH(QI.text_data_en, "obj_heartdefeated_201_0", "  Our fate rests &  upon you.../");
  DH(QI.text_data_en, "obj_heartdefeated_201_1", "  \\[C]^1!&  Stay determined.../%%");
  DH(QI.text_data_en, "obj_heartdefeated_202_0", "  You're going to&  be alright!/");
  DH(QI.text_data_en, "obj_heartdefeated_202_1", "  \\[C]^1!&  Stay determined.../%%");
