  DH(QI.text_data_en, "obj_icecap_149", "OK!&I'll&ignore&you too.");
  DH(QI.text_data_en, "obj_icecap_150", "Better&a hatter&than a&HATER.");
  DH(QI.text_data_en, "obj_icecap_156", "HELLO???&My hat's&up here.");
