  DH(QI.text_data_en, "obj_icecap_177", "That's&the best&one in&a while!");
  DH(QI.text_data_en, "obj_icecap_182", "%%%");
  DH(QI.text_data_en, "obj_icecap_374", "* It's snowing dandruff.");
