  DH(QI.text_data_en, "obj_icecap_npcg_78", "* .../");
  DH(QI.text_data_en, "obj_icecap_npcg_79", "* ... please?/%%");
  DH(QI.text_data_en, "obj_icecap_npcr_70", "* We all live in the woods^1,&  so no one can tell us&  what to do!/");
