  DH(QI.text_data_en, "obj_maddummy_259", "\\E1OWWWW^1, you&DUMMIES!!/");
  DH(QI.text_data_en, "obj_maddummy_260", "\\XWatch where you're&aiming your \\RMAGIC\\X &attacks!/");
  DH(QI.text_data_en, "obj_maddummy_261", "\\E3.../");
  DH(QI.text_data_en, "obj_maddummy_262", "\\XHey^1!&You^1! \\E2Forget&I said anything&about \\RMAGIC\\X!!!/%%");
  DH(QI.text_data_en, "obj_maddummy_319", "Foolish^1.&Foolish^1!&FOOLISH!/");
  DH(QI.text_data_en, "obj_maddummy_320", "Even if you attack&my vessel^1, you'll&NEVER hurt me!/");
