  DH(QI.text_data_en, "obj_mettatonb_quiz_255", "LET'S START WITH&AN EASY ONE!!/%%");
  DH(QI.text_data_en, "obj_mettatonb_quiz_258", "HERE'S YOUR TERRIFIC&PRIZE!/%%");
  DH(QI.text_data_en, "obj_mettatonb_quiz_262", "ENOUGH ABOUT YOU.&LET'S TALK ABOUT ME!/%%");
  DH(QI.text_data_en, "obj_mettatonb_quiz_266", "HERE'S ANOTHER EASY&ONE FOR YOU!/%%");
  DH(QI.text_data_en, "obj_mettatonb_quiz_270", "DON'T 'COUNT'&ON YOUR VICTORY.../%%");
