  DH(QI.text_data_en, "obj_mettatonex_639", "* Mettaton.");
  DH(QI.text_data_en, "obj_mettatonex_640", "* Mettaton.");
  DH(QI.text_data_en, "obj_mettatonex_641", "* Mettaton.");
