  DH(QI.text_data_en, "obj_questionasker_176", "* The quiz show continues.");
  DH(QI.text_data_en, "obj_questionasker_538", "OH^1! OH^1! I KNOW&THIS ONE!!!&IT'S SNAIL ICE&CREAM!!!!!!!^1!%");
  DH(QI.text_data_en, "obj_questionasker_539", "IN THE FOURTH&CHAPTER EVERYONE&GOES TO THE&BEACH!!!%");
  DH(QI.text_data_en, "obj_questionasker_540", "AND SHE BUYS&ICE CREAM FOR&ALL OF HER&FRIENDS!!!!%");
  DH(QI.text_data_en, "obj_questionasker_541", "BUT IT'S SNAIL&FLAVOR AND SHE'S&THE ONLY ONE&WHO WANTS IT!!!!!!%");
  DH(QI.text_data_en, "obj_questionasker_542", "IT'S ONE OF MY&FAVORITE PARTS&OF THE GAME&BECAUSE%");
  DH(QI.text_data_en, "obj_questionasker_543", "IT'S ACTUALLY A&VERY POWERFUL&message abou^1t&friendshi^1p and..^2.%%");
  DH(QI.text_data_en, "obj_questionasker_566", "ALPHYS^1,&ALPHYS^1,&ALPHYS./");
  DH(QI.text_data_en, "obj_questionasker_567", "YOU AREN'T HELPING&OUR CONTESTANT,&ARE YOU?/");
  DH(QI.text_data_en, "obj_questionasker_568", "OOOOOOH!!!&YOU SHOULD HAVE&TOLD ME./");
