  DH(QI.text_data_en, "obj_questionasker_570", "YOU'LL BE SURE&TO KNOW THE&ANSWER TO!/%%");
  DH(QI.text_data_en, "obj_questionasker_598", "ALPHYS^1, ALPHYS^1,&ALPHYS./");
  DH(QI.text_data_en, "obj_questionasker_599", "YOU AREN'T HELPING&OUR CONTESTANT,&ARE YOU?/");
  DH(QI.text_data_en, "obj_questionasker_600", "OOOOOOH!!!&YOU SHOULD HAVE&TOLD ME./");
  DH(QI.text_data_en, "obj_questionasker_601", "I'LL ASK A&QUESTION.../");
  DH(QI.text_data_en, "obj_questionasker_602", "YOU'LL BE SURE&TO KNOW THE&ANSWER TO!/%%");
  DH(QI.text_data_en, "obj_questionasker_607", "SEE, ALPHYS?&I TOLD YOU IT&WAS OBVIOUS./");
  DH(QI.text_data_en, "obj_questionasker_608", "EVEN THE HUMAN&FIGURED IT OUT./");
  DH(QI.text_data_en, "obj_questionasker_609", "YES, SHE SCRAWLS&HER NAME IN THE&MARGINS OF HER&NOTES./");
  DH(QI.text_data_en, "obj_questionasker_610", "SHE NAMES PROGRAMMING&VARIABLES AFTER&HER./");
