  DH(QI.text_data_en, "obj_questionasker_615", "PROBABILITY OF&CRUSH:&101 PERCENT./");
  DH(QI.text_data_en, "obj_questionasker_616", "MARGIN OF ERROR.&ONE PERCENT./%%");
