  DH(QI.text_data_en, "obj_tordogcall_154", "* (You hear a distant voice.)\\TT/");
  DH(QI.text_data_en, "obj_tordogcall_155", "* Helloooo^1?&* Little puppy...?/");
  DH(QI.text_data_en, "obj_tordogcall_156", "* Where are you...?/");
