  DH(QI.text_data_en, "obj_tordogcall_160", "* (The snoring resumes.)/");
  DH(QI.text_data_en, "obj_tordogcall_161", "\\TS \\F0 \\T0 %");
  DH(QI.text_data_en, "obj_tordogcall_162", "* Click.../%%");
  DH(QI.text_data_en, "obj_tordogcall_176", "* Ring.../");
