  DH(QI.text_data_en, "obj_tordogcall_179", "* (Achoo!)/");
  DH(QI.text_data_en, "obj_tordogcall_180", "* (It sounds like a small^1,&  white dog sneezing in its&  sleep.)/");
  DH(QI.text_data_en, "obj_tordogcall_181", "* (You hear a distant voice.)\\TT/");
  DH(QI.text_data_en, "obj_tordogcall_182", "* Here^1, pup-pup-puppy!/");
