function control_init() {
  for (let r7 = 2; r7 >= 0; r7--) {
    (QI.control_state ??= [])[r7] = 0;
    (QI.control_pressed ??= [])[r7] = 0;
    (QI.control_new_state ??= [])[r7] = 0;
  }
}
